import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    last_seen = {}
    ans = n + 1

    for i, x in enumerate(a):
        if x in last_seen:
            ans = min(ans, i - last_seen[x] + 1)
        last_seen[x] = i

    print(-1 if ans == n + 1 else ans)

if __name__ == "__main__":
    main()

